export class EntropyScoringSystem {
  static calculateEntropy(probabilities) {
    return -probabilities.reduce((sum, p) => sum + (p * Math.log2(p || 1)), 0);
  }

  static evaluateConsistency(probabilities) {
    const entropy = EntropyScoringSystem.calculateEntropy(probabilities);
    return entropy < 1.5 ? 'consistent' : 'inconsistent';
  }
}

// Example usage
const probabilities = [0.7, 0.2, 0.1];
const consistency = EntropyScoringSystem.evaluateConsistency(probabilities);
console.log(`Consistency: ${consistency}`);